"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def addMatrices(A, B, rows, cols):
    result = [[None for _ in range(cols)] for _ in range(rows)]
    for i in range(0, rows):
        for j in range(0, cols):
            result[i][j] = (A[i][j] + B[i][j])
    return result
print(addMatrices([[1, 2], [3, 4]], [[5, 6], [7, 8]], 2, 2))